-- ============================================================
-- Migration — Correction des quiz de formation calculée côté serveur
-- (suite du 08/08/2026 : Fouka choisit explicitement de garder la
-- certification déjà attribuée à Mikael Athanase Ruffine telle quelle,
-- et de fermer la limite documentée dans
-- migration-audit-08-08-formation-rewards-serveur.sql : "la correction
-- du quiz reste calculée côté client".)
--
-- Deux failles fermées ici, découvertes en creusant ce point :
--
-- 1. FORMATION_QUIZ_CATALOG (SportVision-OS-Full.html) contenait les
--    1133 questions ET leurs bonnes réponses en clair dans le JS envoyé
--    au navigateur — n'importe qui pouvait lire le code source et
--    connaître toutes les réponses sans jamais se tromper.
-- 2. La table formations_quiz_custom (quiz créés par l'admin pour les
--    formations personnalisées) avait une policy SELECT ouverte à tout
--    utilisateur connecté, exposant reponse_correcte directement par
--    l'API REST — pire que le cas 1 : pas besoin de lire le JS, une
--    seule requête suffisait, et ça touchait aussi les futurs quiz
--    créés depuis l'admin, pas seulement les 1133 questions intégrées.
--
-- Correction : les bonnes réponses ne sont plus JAMAIS envoyées au
-- client avant la soumission. Nouvelle table formation_quiz_questions
-- (réplique serveur des 1133 questions intégrées, verrouillée en
-- lecture), policy formations_quiz_custom resserrée à l'admin, et deux
-- RPC SECURITY DEFINER : rpc_get_custom_quiz (questions+options SANS
-- réponse, pour l'utilisateur qui passe le quiz) et rpc_submit_quiz
-- (note réellement calculée côté serveur à partir des réponses
-- soumises, plus jamais un score/pass déclaré par le client). Remplace
-- rpc_quiz_bonus (supprimée : elle acceptait encore p_score/p_pass du
-- client, donc restait un moyen de contourner cette même correction).
--
-- Limite résiduelle assumée : rpc_submit_quiz renvoie, pour chaque
-- question soumise, la bonne réponse (nécessaire pour l'écran "Bonne
-- réponse : …" affiché après validation, comme avant). Un utilisateur
-- qui soumettrait des réponses au hasard à répétition pourrait donc
-- reconstituer le corrigé question par question au fil des tentatives
-- — mais cela suppose d'être inscrit à la formation et de repasser le
-- quiz autant de fois qu'il y a de questions (tracé dans
-- formation_inscriptions à chaque soumission), très différent de lire
-- instantanément toutes les réponses de toutes les formations dans le
-- JS ou par une seule requête REST comme c'était le cas avant. Fermer
-- complètement ce dernier point (ex : limiter le nombre de tentatives)
-- n'a pas été demandé et n'est pas fait ici.
--
-- Idempotent (create or replace / drop + create policy / on conflict).
-- À exécuter dans Supabase → SQL Editor, après
-- migration-audit-08-08-formation-rewards-serveur.sql.
-- ============================================================


-- ─── 1. Table de référence : banque de questions intégrées ────────────────
-- Réplique serveur de FORMATION_QUIZ_CATALOG (SportVision-OS-Full.html),
-- correct_index inclus. Extrait le 08/08/2026 — si le catalogue JS est
-- modifié (nouvelle question, formation ajoutée), cette table doit être
-- régénérée pour rester la source de vérité. q_index correspond à la
-- position dans le tableau de questions de la formation (0-indexé),
-- exactement l'ordre d'affichage côté client.
drop table if exists formation_quiz_questions;
create table formation_quiz_questions (
  id             uuid default gen_random_uuid() primary key,
  formation_id   text not null,
  q_index        integer not null,
  question       text not null,
  options        jsonb not null,
  correct_index  integer not null,
  unique(formation_id, q_index)
);

alter table formation_quiz_questions enable row level security;
-- Aucune policy SELECT pour les utilisateurs normaux : cette table ne
-- doit jamais être lisible directement par un utilisateur en train de
-- passer un quiz (elle contient la bonne réponse). Seul un admin peut la
-- consulter directement (aperçu dans le panneau d'administration des
-- formations) ; le passage du quiz lui-même passe par rpc_submit_quiz,
-- qui lit cette table en SECURITY DEFINER (donc indépendamment des
-- policies RLS ci-dessous).
drop policy if exists "fqq_admin_select" on formation_quiz_questions;
create policy "fqq_admin_select" on formation_quiz_questions for select using (
  exists (select 1 from profiles where id = auth.uid() and role = 'admin')
);



-- ─── 2. formations_quiz_custom : verrouiller la lecture à l'admin ─────────
-- fqc_select (migration-formations-admin.sql) autorisait tout utilisateur
-- connecté à lire la table entière, reponse_correcte inclus. Resserré au
-- même principe que fqq_admin_select ci-dessus : seul l'admin (qui écrit
-- déjà ces quiz) peut les lire directement. Le passage du quiz par un
-- collaborateur passe désormais par rpc_get_custom_quiz (sans la bonne
-- réponse) et rpc_submit_quiz (notation serveur).
drop policy if exists "fqc_select" on formations_quiz_custom;
create policy "fqc_select" on formations_quiz_custom for select using (
  exists (select 1 from profiles where id = auth.uid() and role = 'admin')
);


-- ─── 3. RPC : récupérer un quiz personnalisé sans les réponses ────────────
-- Remplace la lecture directe de formations_quiz_custom dans lancerQuiz()
-- (SportVision-OS-Full.html), devenue impossible pour un non-admin après
-- le resserrement de fqc_select ci-dessus. Ne renvoie jamais
-- reponse_correcte.
create or replace function rpc_get_custom_quiz(p_formation_id text)
returns jsonb
language sql
security definer
set search_path = public
as $$
  select coalesce(
    jsonb_agg(jsonb_build_object('question', question, 'options', options) order by ordre),
    '[]'::jsonb
  )
  from formations_quiz_custom
  where formation_id = p_formation_id;
$$;

grant execute on function rpc_get_custom_quiz(text) to authenticated;


-- ─── 4. RPC : soumission et notation serveur d'un quiz ─────────────────────
-- Remplace entièrement la notation client (qs.forEach(...correct++...)
-- dans soumettreQuiz()) : le client envoie uniquement les réponses
-- choisies (p_answers, tableau jsonb de l'index sélectionné par question,
-- dans l'ordre d'affichage — même ordre que rpc_get_custom_quiz /
-- formation_quiz_questions.q_index), jamais un score ou un résultat
-- pass/fail. Priorité aux questions personnalisées (formations_quiz_custom)
-- si la formation en a, sinon banque intégrée (formation_quiz_questions) —
-- même logique de repli que l'ancien code client. Remplace rpc_quiz_bonus
-- (supprimée ci-dessous), qui acceptait encore p_score/p_pass du client.
create or replace function rpc_submit_quiz(p_inscription_id uuid, p_answers jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_insc formation_inscriptions%rowtype;
  v_reward formation_rewards%rowtype;
  v_role text;
  v_custom_count integer;
  v_total integer := 0;
  v_correct integer := 0;
  v_pos integer := 0;
  v_given integer;
  v_correct_index integer;
  v_row record;
  v_results jsonb := '[]'::jsonb;
  v_score integer;
  v_pass boolean;
  v_already_passed boolean;
  v_bonus integer := 0;
begin
  if v_uid is null then
    raise exception 'Authentification requise.';
  end if;

  select * into v_insc from formation_inscriptions
    where id = p_inscription_id and collaborateur_id = v_uid;
  if not found then
    raise exception 'Inscription introuvable ou non autorisée.';
  end if;

  v_already_passed := coalesce(v_insc.quiz_passe, false);

  select count(*) into v_custom_count from formations_quiz_custom where formation_id = v_insc.formation_id;

  for v_row in (
    select reponse_correcte as correct_index from formations_quiz_custom
      where formation_id = v_insc.formation_id and v_custom_count > 0
      order by ordre
    union all
    select correct_index from formation_quiz_questions
      where formation_id = v_insc.formation_id and v_custom_count = 0
      order by q_index
  )
  loop
    v_correct_index := v_row.correct_index;
    v_given := nullif(p_answers ->> v_pos, '')::integer;
    if v_given is not null and v_given = v_correct_index then
      v_correct := v_correct + 1;
    end if;
    v_results := v_results || jsonb_build_object(
      'q_index', v_pos, 'correct_index', v_correct_index,
      'given', v_given, 'ok', coalesce(v_given = v_correct_index, false)
    );
    v_total := v_total + 1;
    v_pos := v_pos + 1;
  end loop;

  if v_total = 0 then
    raise exception 'Aucun quiz pour cette formation.';
  end if;

  v_score := round(v_correct::numeric / v_total * 100);
  v_pass := v_score >= 70;

  update formation_inscriptions set score_quiz = v_score, quiz_passe = v_pass
    where id = p_inscription_id;

  select * into v_reward from formation_rewards where formation_id = v_insc.formation_id;
  select role into v_role from profiles where id = v_uid;
  if found and v_role = 'photo' and v_pass and not v_already_passed then
    v_bonus := round(v_reward.xp * 0.3);
    if v_bonus > 0 then
      values (v_uid, v_bonus, 'bonus', p_inscription_id, 'formation_inscriptions', 'Quiz réussi', v_uid);
      update profiles set xp = coalesce(xp,0) + v_bonus where id = v_uid;
    end if;
  end if;

  return jsonb_build_object(
    'score', v_score, 'pass', v_pass, 'correct', v_correct, 'total', v_total,
    'bonus_xp', v_bonus, 'results', v_results
  );
end;
$$;

grant execute on function rpc_submit_quiz(uuid, jsonb) to authenticated;


-- ─── 5. Suppression de rpc_quiz_bonus ───────────────────────────────────────
-- Superflue et dangereuse à garder : elle acceptait encore p_score/p_pass
-- fournis par le client (migration-audit-08-08-formation-rewards-
-- serveur.sql, section 3) — un appel direct à cette RPC avec pass:true
-- aurait contourné la correction serveur ci-dessus. Remplacée par
-- rpc_submit_quiz, qui ne fait plus confiance qu'aux réponses brutes.
drop function if exists rpc_quiz_bonus(uuid, integer, boolean);
